properties_schema:
[
  {
    "displayName": "Authentication",
    "name": "authentication",
    "type": "hidden",
    "default": "triggerOAuth2",
    "options": [
      {
        "name": "OAuth2 (recommended)",
        "value": "triggerOAuth2"
      }
    ]
  },
  {
    "displayName": "Document",
    "name": "documentId",
    "type": "resourceLocator",
    "default": {
      "mode": "list",
      "value": ""
    },
    "required": true
  },
  {
    "displayName": "Sheet",
    "name": "sheetName",
    "type": "resourceLocator",
    "default": {
      "mode": "list",
      "value": ""
    },
    "required": true,
    "typeOptions": {
      "loadOptionsDependsOn": [
        "documentId.value"
      ]
    }
  },
  {
    "displayName": "Trigger On",
    "name": "event",
    "type": "options",
    "default": "anyUpdate",
    "description": "It will be triggered also by newly created columns (if the ''Columns to Watch'' option is not set)",
    "options": [
      {
        "name": "Row Added",
        "value": "rowAdded"
      },
      {
        "name": "Row Updated",
        "value": "rowUpdate"
      },
      {
        "name": "Row Added or Updated",
        "value": "anyUpdate"
      }
    ],
    "required": true
  },
  {
    "displayName": "Include in Output",
    "name": "includeInOutput",
    "type": "options",
    "default": "new",
    "description": "This option will be effective only when automatically executing the workflow",
    "options": [
      {
        "name": "New Version",
        "value": "new"
      },
      {
        "name": "Old Version",
        "value": "old"
      },
      {
        "name": "Both Versions",
        "value": "both"
      }
