        "typeOptions": {
          "loadOptionsDependsOn": [
            "sheetName.value"
          ],
          "loadOptionsMethod": "getSheetHeaderRowAndSkipEmpty"
        },
        "default": [],
        "displayOptions": {
          "show": {
