      },
      {
        "displayName": "View Content Link",
        "name": "viewContentLink",
        "type": "boolean",
        "default": false,
        "description": "Whether to remove content logging for sensitive emails"
      }
    ],
    "displayOptions": {
      "show": {
        "operation": [
          "sendHtml",
