  {
    "displayName": "Operation",
    "name": "operation",
    "type": "options",
    "default": "getAll",
    "options": [
      {
        "name": "Create",
        "value": "create",
        "description": "Create a new user",
        "routing": {
          "request": {
            "method": "POST",
            "url": "/api/v1/users/",
            "qs": {
              "activate": "={{$parameter["activate"]}}"
            },
            "returnFullResponse": true
          }
        },
        "action": "Create a new user"
      },
      {
        "name": "Delete",
        "value": "delete",
        "description": "Delete an existing user",
        "routing": {
          "request": {
            "method": "DELETE",
            "url": "={{"/api/v1/users/" + $parameter["userId"]}}",
            "returnFullResponse": true
          },
          "output": {
            "postReceive": [
              {
                "type": "set",
                "properties": {
                  "value": "={{ { "success": true } }}"
                }
              }
            ]
          }
        },
        "action": "Delete a user"
      },
      {
        "name": "Get",
        "value": "get",
        "description": "Get details of a user",
        "routing": {
          "request": {
            "method": "GET",
            "url": "={{"/api/v1/users/" + $parameter["userId"]}}",
            "returnFullResponse": true,
            "qs": {}
          },
          "output": {
            "postReceive": [
              null
            ]
          }
        },
        "action": "Get a user"
      },
      {
