              "search": "={{$parameter["searchQuery"]}}"
            },
            "returnFullResponse": true
          },
          "output": {
            "postReceive": [
              null
            ]
          },
          "send": {
            "paginate": true
          },
          "operations": {}
        },
        "action": "Get many users"
